var aiUi=require("$:/plugins/huwiki/ai/i18n.js");
/*\
title: $:/plugins/huwiki/ai/chat-library-widget.js
type: application/javascript
module-type: widget

Native TiddlyWiki chat library and preview-first ChatGPT archive importer.
\*/
(function(){
"use strict";
var consent=require("$:/plugins/huwiki/ai/consent.js");
var Widget=require("$:/core/modules/widgets/widget.js").widget;
var chat=require("$:/plugins/huwiki/ai/chat-engine.js");
var adapters=require("$:/plugins/huwiki/ai/model-adapters.js");
var expert=require("$:/plugins/huwiki/ai/wiki-knowledge.js");
var msgtools=require("$:/plugins/huwiki/ai/message-actions.js");
var capabilities=require("$:/plugins/huwiki/ai/model-capabilities.js");
var imageReplies=require("$:/plugins/huwiki/ai/image-replies.js");
var jobs=Object.create(null),failed=Object.create(null);
var IMAGE_MODES={fast:{size:900,label:"Hurtig"},balanced:{size:1200,label:"Balanceret"},detail:{size:1500,label:"Detaljeret"}};
function durationLabel(ms){var s=Math.max(0,Math.floor(Number(ms||0)/1000));return String(Math.floor(s/60)).padStart(2,"0")+":"+String(s%60).padStart(2,"0");}
function imageMode(){var s=getSettings();return IMAGE_MODES[s.imageMode]?s.imageMode:"balanced";}
var KEY="huwiki-ai-settings-v0.1",DRAFT="$:/temp/huwiki/ai/chat-draft";
function getSettings(){try{return JSON.parse(window.localStorage.getItem(KEY)||"{}");}catch(e){return {};}}
function el(parent,tag,klass,text){var n=parent.ownerDocument.createElement(tag);if(klass)n.className=klass;if(text!==undefined)n.textContent=String(text);parent.appendChild(n);return n;}
function btn(parent,text,click,klass){var n=el(parent,"button","huwiki-ai-button "+(klass||""),text);n.type="button";n.addEventListener("click",click);return n;}
function field(parent,label,value,change){var wrap=el(parent,"label","huwiki-ai-field");el(wrap,"span","huwiki-ai-label",label);var n=el(wrap,"input","huwiki-ai-input");n.value=value||"";n.addEventListener("input",function(){change(n.value);});return n;}
function incomingDraft(){
  var draft=$tw.wiki.getTiddler(DRAFT),source=$tw.wiki.getTiddler("$:/temp/huwiki/ai/chat-source");
  if(!draft || !draft.fields.text)return "";
  var text=draft.fields.text;
  if(source && source.fields.text)text=aiUi.text("Læs denne tiddler (")+source.fields.text+aiUi.text(") og hjælp mig med at forbedre eller organisere indholdet:\n\n")+text.slice(0,6500);
  $tw.wiki.deleteTiddler(DRAFT);$tw.wiki.deleteTiddler("$:/temp/huwiki/ai/chat-source");
  return text;
}
function Library(node,options){this.initialise(node,options);}
Library.prototype=new Widget();
Library.prototype.execute=function(){};
Library.prototype.render=function(parent,nextSibling){this.computeAttributes();if(aiUi.reuseWidget(this,parent,nextSibling,"chat-library-widget.js"))return;
  this.parentDomNode=parent;this.computeAttributes();this.execute();this.importOnly=this.getAttribute("mode","chat")==="import";this.root=this.document.createElement("div");
  this.root.className="huwiki-ai-chat-library huw-ai-edition";parent.insertBefore(this.root,nextSibling);this.domNodes=[this.root];
  this.selected=this.getAttribute("conversation","");this.conversationDrafts=Object.create(null);this.registerGroup="recent";this.registerTag="";this.editingConversation=null;this.query="";this.importQuery="";this.notice="";this.error=false;this.importPreview=null;this.importChosen={};this.busy=false;
  this.settings=getSettings();this.draft="";this.proposals=[];this.showProposals=false;this.vaultConnections=[];this.vaultReady=false;
  this.tiddlerDialog=null;this.scrollLatest=false;this.waitTimer=null;this.modelChoices={};this.modelLoading=false;this.modelError="";this.importExpanded={};this.importSkipped={};
  this.imageDraft=[];this.sessionImages=Object.create(null);this.outputImages=Object.create(null);this.imageBusy=false;this.replyMode="chat";this.imageModelChoices={};
  var init=incomingDraft();if(init)this.draft=init;
  this.draw();this.loadPrivateConnections();
};
Library.prototype.refresh=function(changed){if(this._aiUiDelegate)return this._aiUiDelegate.refresh(changed);
  if(changed && changed[DRAFT]) {
    var incoming=incomingDraft();
    if(incoming){this.draft=incoming;this.draw();return true;}
  }
  if(changed){
    var self=this;var touches=Object.keys(changed).some(function(k){var t=$tw.wiki.getTiddler(k),tags=t&&t.fields.tags||[];return k===self.selected || (self.selected&&k.indexOf(self.selected+" / ")===0) || tags.indexOf(chat.CONVERSATION_TAG)>=0 || tags.indexOf(chat.MESSAGE_TAG)>=0 || !!changed[k].deleted;});
    if(touches){this.draw();return true;}
  }
  if(changed&&changed["$:/language"]){this.draw();return true;}return false;
};
Library.prototype.message=function(text,bad){this.notice=text;this.error=!!bad;this.draw();};
Library.prototype.switchConversation=function(title){
  this.conversationDrafts=this.conversationDrafts||Object.create(null);
  if(this.selected)this.conversationDrafts[this.selected]={text:this.draft,images:this.imageDraft,replyMode:this.replyMode};
  var saved=this.conversationDrafts[title]||{};
  this.selected=title||"";this.draft=saved.text||"";this.imageDraft=saved.images||[];this.replyMode=saved.replyMode||"chat";
  this.proposals=[];this.tiddlerDialog=null;this.editingConversation=null;this.notice="";this.error=false;this.scrollLatest=true;
};
Library.prototype.newConversation=function(){
  var incoming=this.selected?"":this.draft;
  var title=chat.createConversation($tw.wiki,$tw.Tiddler,aiUi.text("Ny chat · ")+new Date().toLocaleString(aiUi.locale()),{origin:"HUWiki AI",provider:""});
  this.switchConversation(title);this.draft=incoming;
  var t=$tw.wiki.getTiddler(title);
  this.editingConversation={caption:t.fields.caption,topic:"",tags:""};
  this.notice=aiUi.text("Ny, separat chat. Giv den gerne en titel. AI-forbindelsen vælges, når du vil sende.");
  this.draw();
  var name=this.root.querySelector(".huw-ai-chat-details input");if(name){name.focus();name.select();}
};
Library.prototype.drawRegister=function(aside){
  var self=this,all=chat.conversations($tw.wiki);
  el(aside,"h3",null,aiUi.text("Dine chats"));
  btn(aside,aiUi.text("+ Ny chat"),function(){self.newConversation();},"huw-ai-primary huw-ai-register-new");
  var search=field(aside,aiUi.text("Søg i chats"),this.query,function(v){self.query=v;self.draw();
    var input=self.root.querySelector(".huw-ai-chat-index input");if(input){input.focus();input.setSelectionRange(v.length,v.length);}});
  search.setAttribute("aria-label",aiUi.text("Søg i chats"));search.placeholder=aiUi.text("Titel, emne, tag eller model");
  var grouping=el(aside,"label","huwiki-ai-field");el(grouping,"span","huwiki-ai-label",aiUi.text("Gruppér efter"));
  var group=el(grouping,"select","huwiki-ai-input");
  [["recent",aiUi.text("Seneste aktivitet")],["topic",aiUi.text("Emne")],["model","AI-model"]].forEach(function(item){var o=el(group,"option",null,item[1]);o.value=item[0];});
  group.value=this.registerGroup||"recent";group.addEventListener("change",function(){self.registerGroup=group.value;self.draw();});
  var tags=[];all.forEach(function(c){c.tags.forEach(function(tag){if(tags.indexOf(tag)<0)tags.push(tag);});});tags.sort();
  if(tags.length){
    var label=el(aside,"label","huwiki-ai-field");el(label,"span","huwiki-ai-label","Tag");
    var select=el(label,"select","huwiki-ai-input");var any=el(select,"option",null,aiUi.text("Alle tags"));any.value="";
    tags.forEach(function(tag){var o=el(select,"option",null,tag);o.value=tag;});select.value=this.registerTag||"";
    select.addEventListener("change",function(){self.registerTag=select.value;self.draw();});
  }else this.registerTag="";
  var visible=chat.filterConversations(all,this.query,this.registerTag);
  el(aside,"p","huwiki-ai-muted",visible.length+aiUi.text(" af ")+all.length+aiUi.text(" chats"));
  var list=el(aside,"div","huw-ai-register-list"),groups=Object.create(null),order=[];
  visible.forEach(function(c){
    var key=self.registerGroup==="topic"?(c.topic||aiUi.text("Uden emne")):self.registerGroup==="model"?(c.models.join(" · ")||aiUi.text("Ingen model brugt endnu")):"";
    if(!groups[key]){groups[key]=[];order.push(key);}groups[key].push(c);
  });
  if(this.registerGroup&&this.registerGroup!=="recent")order.sort(function(a,b){return a.localeCompare(b,"da");});
  order.forEach(function(key){
    if(key)el(list,"h4","huw-ai-register-group",key);
    groups[key].forEach(function(c){
      var row=btn(list,"",function(){self.switchConversation(c.title);self.draw();},"huw-ai-chat-link"+(self.selected===c.title?" huw-ai-chat-active":""));
      row.setAttribute("aria-label",aiUi.text("Åbn chat: ")+c.caption);row.setAttribute("aria-pressed",String(self.selected===c.title));
      el(row,"strong",null,c.caption);el(row,"small",null,c.count+aiUi.text(" beskeder")+(c.topic?" · "+c.topic:""));
      if(c.tags.length)el(row,"small","huw-ai-register-tags",c.tags.join(" · "));
      if(c.models.length)el(row,"small",null,c.models.join(" · "));
    });
  });
  if(!visible.length)el(list,"p","huwiki-ai-help",all.length?aiUi.text("Ingen chats matcher søgningen."):aiUi.text("Start din første chat med knappen ovenfor."));
};
Library.prototype.drawConversationDetails=function(root,t){
  var self=this;
  if(!this.editingConversation){
    var topic=t.fields["ai-topic"],tags=chat.conversationTags(t.fields.tags||[]);
    if(topic||tags.length)el(root,"p","huwiki-ai-muted",[topic,tags.join(" · ")].filter(Boolean).join(" · "));
    btn(root,aiUi.text("Titel, emne og tags"),function(){self.editingConversation={caption:t.fields.caption||t.fields.title,topic:topic||"",tags:tags.join(", ")};self.draw();},"huw-ai-secondary");
    return;
  }
  var d=this.editingConversation,box=el(root,"section","huw-ai-chat-details");
  field(box,aiUi.text("Chattitel"),d.caption,function(v){d.caption=v;});
  field(box,aiUi.text("Emne (valgfrit)"),d.topic,function(v){d.topic=v;});
  field(box,aiUi.text("Tags (adskilt med komma)"),d.tags,function(v){d.tags=v;});
  btn(box,aiUi.text("Gem chatoplysninger"),function(){
    if(!d.caption.trim()){self.notice=aiUi.text("Skriv en titel til chatten.");self.error=true;self.draw();return;}
    chat.updateConversation($tw.wiki,$tw.Tiddler,self.selected,d);self.editingConversation=null;self.message(aiUi.text("Chatoplysninger gemt."),false);
  },"huw-ai-primary");
  btn(box,aiUi.text("Annullér"),function(){self.editingConversation=null;self.draw();},"huw-ai-secondary");
};

// Deliberately render only passive prose here. AI widgets, HTML and macros are
// shown as source; they must never execute merely because a model replied.
function drawWikiText(parent,text){
  function inline(node,value){
    var rx=/(''([^'\n]+)''|`([^`\n]+)`|\[\[([^\]\n]+)\]\])/g,last=0,m;
    while((m=rx.exec(value))){
      if(m.index>last)el(node,"span",null,value.slice(last,m.index));
      if(m[2])el(node,"strong",null,m[2]);
      else if(m[3])el(node,"code",null,m[3]);
      else el(node,"span","huw-ai-wiki-link",m[4].split("|")[0]);
      last=rx.lastIndex;
    }if(last<value.length)el(node,"span",null,value.slice(last));
  }
  msgtools.parseBlocks(text).forEach(function(block){
    if(block.kind!=="text"){
      var panel=el(parent,"section","huw-ai-code-panel"),toolbar=el(panel,"div","huw-ai-code-toolbar");
      el(toolbar,"span",null,block.language||aiUi.text("Kode"));
      btn(toolbar,aiUi.text("Kopiér kode"),function(){copyCode(block.text,function(){},function(){});},"huw-ai-secondary");
      el(el(panel,"pre"),"code",null,block.text);return;
    }
    var stack=[],paragraph=null;
    block.text.split("\n").forEach(function(line){
      var m=line.match(/^([*#]+)\s+(.*)$/);
      if(m){
        paragraph=null;var marks=m[1];
        while(stack.length>marks.length)stack.pop();
        for(var depth=0;depth<marks.length;depth++){
          var type=marks[depth]==="#"?"ol":"ul";
          if(!stack[depth]||stack[depth].type!==type){
            stack.length=depth;
            var host=depth?(stack[depth-1].last||el(stack[depth-1].list,"li")):parent;
            stack.push({type:type,list:el(host,type),last:null});
          }
        }
        var level=stack[marks.length-1];level.last=el(level.list,"li");inline(level.last,m[2]);return;
      }
      stack=[];
      if(!line.trim()){paragraph=null;return;}
      if((m=line.match(/^(!{1,6})\s+(.*)$/))){paragraph=null;inline(el(parent,"h"+m[1].length),m[2]);return;}
      if(!paragraph)paragraph=el(parent,"p");else el(paragraph,"br");inline(paragraph,line);
    });
  });
}

Library.prototype.draw=function(){
  var self=this,r=this.root;if(!r)return;
  var previous=r.querySelector(".huw-ai-chat-stream"),oldScroll=previous?previous.scrollTop:0;
  var wasAtEnd=previous?(previous.scrollHeight-previous.scrollTop-previous.clientHeight<100):true;
  while(r.firstChild)r.removeChild(r.firstChild);
  var top=el(r,"div","huw-ai-section-header");el(top,"h2",null,this.importOnly?aiUi.text("Importér samtaler"):aiUi.text("Chatregister"));
  el(top,"p","huwiki-ai-muted",aiUi.text("Start separate chats, giv dem titler, og find dem igen efter emne, tags eller model."));
  if(this.notice)el(r,"div","huwiki-ai-message"+(this.error?" huw-ai-error":""),aiUi.message(this.notice));
  var tools=el(r,"div","huw-ai-inline-actions");
  if(!this.importOnly)btn(tools,aiUi.text("+ Ny chat"),function(){self.newConversation();},"huw-ai-primary");
  if(this.importOnly)btn(tools,aiUi.text("Vælg ChatGPT-eksport (conversations.json)"),function(){fileInput.click();},"huw-ai-primary");
  else btn(tools,aiUi.text("Importér udvalgte ChatGPT-samtaler →"),function(){self.dispatchEvent({type:"tm-navigate",navigateTo:"HUWiki AI · Import",navigateFromTitle:self.selected||"HUWiki AI · Chatbibliotek"});},"huw-ai-secondary");
  var fileInput=el(tools,"input","huw-ai-hidden");fileInput.type="file";fileInput.accept=".json,application/json";
  fileInput.addEventListener("change",function(){
    var file=fileInput.files && fileInput.files[0];if(!file)return;
    var reader=new FileReader();self.busy=true;self.draw();
    reader.onload=function(){try{
      self.importPreview=chat.parseArchive(reader.result);self.importChosen={};self.importSkipped={};self.importExpanded={};
      self.message(aiUi.text("Fandt ")+self.importPreview.length+" samtaler i "+file.name+aiUi.text(". Vælg tråde nedenfor. Intet er importeret endnu."),false);
    }catch(e){self.importPreview=null;self.message(aiUi.text("Kunne ikke læse eksporten: ")+e.message,true);}finally{self.busy=false;}};
    reader.onerror=function(){self.busy=false;self.message(aiUi.text("Filen kunne ikke læses."),true);};
    reader.readAsText(file,"utf-8");
  });
  if(this.busy)el(r,"p","huwiki-ai-help",aiUi.text("Læser eksportfilen…"));
  if(this.importPreview)this.drawImport(r);
  if(this.importOnly)return;
  var layout=el(r,"div","huw-ai-chat-layout");
  var aside=el(layout,"aside","huw-ai-chat-index");
  this.drawRegister(aside);
  var main=el(layout,"section","huw-ai-chat-main");
  if(this.selected && !$tw.wiki.getTiddler(this.selected))this.selected="";
  if(this.selected)this.drawConversation(main);else {
    el(main,"h3",null,aiUi.text("Velkommen til AI-chatten"));
    el(main,"p",null,aiUi.text("Vælg en chat i registret, eller tryk + Ny chat. Hver chat har sine egne beskeder og sin egen kladde."));
    if(this.draft)el(main,"p",null,aiUi.text("Et eksempel-prompt er klar. Opret en samtale for at bruge det."));
  }
  var stream=r.querySelector(".huw-ai-chat-stream");
  if(stream){
    if(this.scrollLatest || wasAtEnd)stream.scrollTop=stream.scrollHeight;
    else stream.scrollTop=Math.min(oldScroll,stream.scrollHeight);
    this.scrollLatest=false;
  }
  this.restartWaitTimer();
};
Library.prototype.drawImport=function(root){
  var self=this,items=this.importPreview;
  var card=el(root,"section","huwiki-ai-card huw-ai-import");
  var row=el(card,"div","huw-ai-inline-actions");el(row,"h3",null,aiUi.text("ChatGPT-import · forhåndsvisning"));
  btn(row,aiUi.text("Luk import"),function(){self.importPreview=null;self.importChosen={};self.draw();},"huw-ai-secondary");
  el(card,"p","huwiki-ai-help",aiUi.text("Vælg op til 15 samtaler ad gangen. Filer bliver på enheden, indtil du vælger Importér valgte. Kun teksten i den aktive samtalegren importeres. Importerede tiddlere gemmes i din wiki og synkroniseres efter dens normale regler."));
  var selected=Object.keys(this.importChosen).filter(function(k){return self.importChosen[k];}).length;
  btn(row,aiUi.text("Importér valgte (")+selected+")",function(){
    try{
      var choices=items.filter(function(c){return !!self.importChosen[c.id];}).map(function(c){return Object.assign({},c,{messages:c.messages.filter(function(_,i){return !self.importSkipped[c.id+":"+i];})});}).filter(function(c){return c.messages.length>0;});
      var res=chat.importSelected($tw.wiki,$tw.Tiddler,choices);var created=res.filter(function(r){return !r.skipped;});
      self.importPreview=null;self.importChosen={};self.importSkipped={};self.importExpanded={};self.selected=created[0]&&created[0].title||self.selected;
      self.message(aiUi.text("Importerede ")+created.length+" samtaler ("+(res.length-created.length)+" dubletter sprunget over).",false);
    }catch(e){self.message(aiUi.text("Importfejl: ")+e.message,true);}
  },"huw-ai-primary").disabled=selected===0||selected>15;
  var finder=field(card,aiUi.text("Søg i eksporten"),this.importQuery,function(v){
    self.importQuery=v;self.draw();var next=self.root.querySelector(".huw-ai-import .huwiki-ai-input");
    if(next){next.focus();try{next.setSelectionRange(v.length,v.length);}catch(ignore){}}
  });finder.placeholder=aiUi.text("Søg i alle eksporterede samtaler");
  var visible=items.filter(function(c){return !self.importQuery||c.name.toLocaleLowerCase(aiUi.locale()).indexOf(self.importQuery.toLocaleLowerCase(aiUi.locale()))!==-1;});
  el(card,"p","huwiki-ai-help",aiUi.text("Viser ")+Math.min(visible.length,150)+aiUi.text(" af ")+visible.length+aiUi.text(" søgeresultater. Vælg op til 15 pr. import."));
  var list=el(card,"div","huw-ai-import-list");
  el(card,"p","huwiki-ai-help",aiUi.text("Alle samtaler er fravalgt fra starten. Åbn en samtale for at se og fravælge enkelte beskeder. Kontrollér indholdet, før du importerer det til en delt wiki."));
  visible.slice(0,150).forEach(function(c){var line=el(list,"label","huw-ai-import-item");var input=el(line,"input");input.type="checkbox";input.checked=!!self.importChosen[c.id];
    input.addEventListener("change",function(){self.importChosen[c.id]=input.checked;self.draw();});
    var content=el(line,"div");el(content,"strong",null,c.name);el(content,"div","huwiki-ai-muted",c.count+aiUi.text(" beskeder · ")+c.created.toLocaleDateString(aiUi.locale()));
    el(content,"div","huwiki-ai-help",c.preview);
    btn(content,self.importExpanded[c.id]?aiUi.text("Skjul beskeder"):aiUi.text("Gennemse beskeder"),function(){self.importExpanded[c.id]=!self.importExpanded[c.id];self.draw();},"huw-ai-secondary");
    if(self.importExpanded[c.id]){
      var messagesBox=el(content,"div","huw-ai-import-messages");
      c.messages.forEach(function(m,i){
        var key=c.id+":"+i,part=el(messagesBox,"label","huw-ai-import-message"),ck=el(part,"input");
        ck.type="checkbox";ck.checked=!self.importSkipped[key];ck.addEventListener("change",function(){self.importSkipped[key]=!ck.checked;});
        var text=el(part,"span",null,(m.role==="assistant"?"AI: ":aiUi.text("Dig: "))+m.text.slice(0,300)+(m.text.length>300?"…":""));text.title=m.text;
      });
    }
  });

};
Library.prototype.loadPrivateConnections=function(){
  var self=this;
  this.vaultRpc("huPrivateVaultList").then(function(res){
    self.vaultConnections=Array.isArray(res&&res.connections)?res.connections.filter(function(c){return c&&c.id&&adapters.supportedProvider(c.provider);}):[];
    self.vaultReady=true;
    var st=getSettings(),active=self.vaultConnections.some(function(c){return c.id===st.vaultId;});
    if(self.vaultConnections.length && (!active || st.connectionMode!=="vault" && !st._manualChosen)){
      st.connectionMode="vault";st.vaultId=self.vaultConnections[0].id;st.vaultModels=st.vaultModels||{};
      window.localStorage.setItem(KEY,JSON.stringify(st));
    }
    self.draw();
    var c=self.activePrivateConnection();if(c&&!((getSettings().vaultModels||{})[c.id]||c.model))self.refreshModels(c);
  }).catch(function(e){self.vaultReady=true;self.modelError=aiUi.text("Kan ikke hente gemte forbindelser: ")+(e.message||e);self.draw();});
};
Library.prototype.activePrivateConnection=function(){
  var s=getSettings();if(s.connectionMode && s.connectionMode!=="vault")return null;
  return this.vaultConnections.filter(function(c){return c.id===s.vaultId;})[0]||this.vaultConnections[0]||null;
};
Library.prototype.vaultRpc=require("$:/plugins/huwiki/ai/forgeshare.js").rpc;
// Render lightweight Markdown safely using DOM text nodes – never innerHTML from a model.
function inlineText(parent,text){
  var parts=String(text||"").split(/(\*\*[^*]+\*\*|`[^`\n]+`)/g);
  parts.forEach(function(part){
    if(/^\*\*[^*]+\*\*$/.test(part))el(parent,"strong",null,part.slice(2,-2));
    else if(/^`[^`\n]+`$/.test(part))el(parent,"code",null,part.slice(1,-1));
    else parent.appendChild(parent.ownerDocument.createTextNode(part));
  });
}
function drawMarkdown(root,text){
  String(text||"").split(/\n/).forEach(function(line){
    var match=line.match(/^(#{1,5})\s+(.+)/),n;
    if(match){n=el(root,match[1].length>2?"h4":"h3","huw-ai-prose-heading");inlineText(n,match[2]);}
    else {n=el(root,"div","huw-ai-prose-line");inlineText(n,line);}
  });
}
function copyCode(text,success,error){
  if(typeof navigator!=="undefined"&&navigator.clipboard&&navigator.clipboard.writeText){
    navigator.clipboard.writeText(text).then(success).catch(function(){fallbackCopy(text,success,error);});
  }else fallbackCopy(text,success,error);
}
function fallbackCopy(text,success,error){
  try{
    var area=document.createElement("textarea");area.value=text;area.style.position="fixed";area.style.opacity="0";
    document.body.appendChild(area);area.select();var result=document.execCommand("copy");document.body.removeChild(area);
