Library.prototype.connection=function(){
  var s=getSettings(),connection=this.activePrivateConnection();
  if(connection){
    var modelKey=this.replyMode==="image"?"vaultImageModels":"vaultModels";
    var model=(s[modelKey]&&s[modelKey][connection.id])||(this.replyMode==="image"?"":connection.model)||"";
    if(!model)throw new Error(aiUi.text("Vælg model i AI-værkstedet først."));
    if(adapters.isCloud(connection.provider)&&!connection.hasKey)throw new Error(aiUi.text("API-nøgle mangler i ForgeShare-nøgleboksen."));
    return {provider:connection.provider,model:model,viaVault:true,id:connection.id,url:connection.serverUrl||""};
  }
  var p=s.provider||"demo";
  if(p==="demo")throw new Error(aiUi.text("Ingen AI-forbindelse fundet. Opret en forbindelse i ForgeShare-nøgleboksen på ForgeShare."));
  var model=s[p+"Model"],url=s[p+"Url"]||adapters.config(p).defaultUrl;
  if(!model)throw new Error(aiUi.text("Vælg en model i AI-værkstedet først."));
  return {provider:p,model:model,url:url};
};
// Reduce screenshots locally before they reach a model. No uploads or AV saves.
function prepareImage(file,mode){
  return new Promise(function(resolve,reject){
    if(!file || !/^(image\/(png|jpeg|webp))$/.test(file.type||""))return reject(Error(aiUi.text("Vælg PNG, JPEG eller WebP.")));
    if(file.size>12*1024*1024)return reject(Error(aiUi.text("Billedet er over 12 MB. Tag et mindre screenshot.")));
    var began=Date.now(),reader=new FileReader();
    reader.onerror=function(){reject(Error(aiUi.text("Kunne ikke læse billedet.")));};
    reader.onload=function(){
      var im=new Image();
      im.onerror=function(){reject(Error(aiUi.text("Billedet kunne ikke åbnes.")));};
      im.onload=function(){
        try{
          var maxSide=IMAGE_MODES[mode]?IMAGE_MODES[mode].size:1200;
          var scale=Math.min(1,maxSide/Math.max(im.width,im.height));
          var canvas=document.createElement("canvas");canvas.width=Math.max(1,Math.round(im.width*scale));canvas.height=Math.max(1,Math.round(im.height*scale));
          canvas.getContext("2d").drawImage(im,0,0,canvas.width,canvas.height);
          // PNG preserves screenshot text when reasonable; otherwise JPEG keeps API calls small.
          var png=canvas.toDataURL("image/png");var dataUrl=png.length<=2.4*1024*1024?png:canvas.toDataURL("image/jpeg",0.83);
          var k=dataUrl.indexOf(","),data=dataUrl.slice(k+1),mimeType=dataUrl.slice(5,dataUrl.indexOf(";"));
          if(data.length>2.8*1024*1024)throw Error(aiUi.text("Billedet er for stort efter tilpasning. Prøv et mindre udsnit."));
          resolve({mimeType:mimeType,data:data,previewUrl:dataUrl,label:String(file.name||"Screenshot").slice(0,90),
            width:canvas.width,height:canvas.height,bytes:Math.floor(data.length*.75),sourceFile:file,mode:mode,
            prepMs:Date.now()-began});
        }catch(e){reject(e);}
      };
      im.src=reader.result;
    };
    reader.readAsDataURL(file);
  });
}
Library.prototype.acceptImages=function(files){
  var self=this,items=Array.prototype.slice.call(files||[]).filter(function(f){return f&&/^image\//.test(f.type||"");});
  if(!items.length){this.message(aiUi.text("Der blev ikke fundet et billede. Vælg PNG, JPEG eller WebP."),true);return;}
  if(this.imageDraft.length+items.length>2){this.message(aiUi.text("Du kan indsætte op til 2 billeder i ét spørgsmål."),true);return;}
  if(this.imageBusy)return;
  this.imageBusy=true;this.draw();
  Promise.all(items.map(function(f){return prepareImage(f,imageMode());})).then(function(images){
    var bytes=images.concat(self.imageDraft).reduce(function(n,i){return n+i.bytes;},0);
    if(bytes>4*1024*1024)throw Error(aiUi.text("Billederne fylder samlet over 4 MB. Vælg mindre udsnit."));
    self.imageDraft=self.imageDraft.concat(images);self.notice=aiUi.text("Billede indsat. Skriv dit spørgsmål, og vælg Send besked.");self.error=false;
  }).catch(function(e){self.notice=aiUi.text("Kunne ikke indsætte billede: ")+e.message;self.error=true;})
    .then(function(){self.imageBusy=false;self.draw();});
};
Library.prototype.setImageMode=function(mode){
  if(!IMAGE_MODES[mode]||this.imageBusy)return;
  var x=getSettings();x.imageMode=mode;window.localStorage.setItem(KEY,JSON.stringify(x));
  var files=this.imageDraft.map(function(image){return image.sourceFile;}).filter(Boolean),self=this;
  if(!files.length){this.draw();return;}
  this.imageBusy=true;this.draw();
  Promise.all(files.map(function(f){return prepareImage(f,mode);})).then(function(prepared){
    var bytes=prepared.reduce(function(n,im){return n+im.bytes;},0);
    if(bytes>4*1024*1024)throw Error(aiUi.text("Billederne er for store. Vælg Hurtig eller Balanceret."));
    self.imageDraft=prepared;self.notice=aiUi.text("Billedet er tilpasset: ")+aiUi.text(IMAGE_MODES[mode].label)+".";self.error=false;
  }).catch(function(e){self.notice=aiUi.text("Kunne ikke ændre billedstørrelse: ")+e.message;self.error=true;})
    .then(function(){self.imageBusy=false;self.draw();});
};
Library.prototype.request=function(messages,mode,done,signal,images,c,approval){
  if(c.viaVault){
    this.vaultRpc(mode==="image"?"huPrivateVaultAiGenerateImage":"huPrivateVaultAiGenerate",{consent:approval,connectionId:c.id,model:c.model,messages:messages,mode:mode,images:(images||[]).map(function(i){return {mimeType:i.mimeType,data:i.data};})})
      .then(function(reply){if(!reply||!reply.ok)throw Error(aiUi.text("AI-kald afvist af HUWiki."));done(null,reply.content,reply.telemetry||{},reply.images||[]);})
      .catch(function(e){done(e);});
    return;
  }
  var endpoint,request;
  try{
    endpoint=adapters.chatEndpoint(c.provider,c.url);
    request=adapters.completionRequest(c.provider,c.model,adapters.withImageAttachments(c.provider,messages,images||[]),mode);
  }catch(e){done(e);return;}
  fetch(endpoint,{method:"POST",mode:"cors",headers:{"Content-Type":"application/json"},body:JSON.stringify(request),signal:signal})
    .then(function(r){if(!r.ok)return r.text().then(function(t){throw new Error(adapters.explainHttpError(c.provider,r.status,t));});return r.json();})
    .then(function(data){done(null,adapters.parseCompletion(c.provider,data),adapters.timingFromResponse(c.provider,data));})
    .catch(function(e){done(e);});
};
Library.prototype.makeChatRequest=function(isRetry){
  var self=this,title=this.selected,content=this.draft.trim();
  if(jobs[title])return;
  if(!isRetry && !content && !this.imageDraft.length)return;
  if(!isRetry && !content && this.imageDraft.length)content=aiUi.text("Beskriv dette billede, og forklar de vigtigste detaljer.");
  try{this.connection();}catch(e){this.message(e.message,true);return;}
  var images=isRetry?null:this.imageDraft.slice();
  var target=this.connection();
  var replyMode=this.replyMode||"chat";
  if(replyMode==="image"&&images&&images.length){this.message(aiUi.text("Vælg Tekst og SVG til billedanalyse. Billedgenerering bruger en tekstbeskrivelse; fjern vedhæftningerne først."),true);return;}
  if(images && images.length && !capabilities.vision(target.provider,target.model)){
    this.message(aiUi.text("Den valgte model er ikke registreret med billedforståelse. Vælg en billedmodel i modelvælgeren, f.eks. Gemma 4, en Gemini-model eller GPT-4o. Ingen billede er sendt."),true);return;
  }
  var approval=consent.approve(target,{da:aiUi.text("Din besked, op til 20 samtalebeskeder, AI-instruktioner og eventuelle vedhæftede billeder. Samtalen gemmes i wikien."),en:"Your message, up to 20 conversation messages, AI instructions and any attached images. The conversation is saved in the wiki."});
  if(!approval)return;
  if(!isRetry){
    var label=images.length?"\n\n["+images.length+aiUi.text(" midlertidigt vedhæftede billede(r) – ikke gemt i AV]"):"";
    var imageMessage=chat.addMessage($tw.wiki,$tw.Tiddler,title,"user",content+label,new Date());
    if(images.length)this.sessionImages[imageMessage]=images;
    this.draft="";this.imageDraft=[];
  }
  delete failed[title];
  var conversation=chat.messagesFor($tw.wiki,title);
  var last=conversation.slice().reverse().filter(function(m){return m.role==="user";})[0];
  if(!last)return;
  if(isRetry)images=(this.sessionImages[last.title]||[]).slice();
  if(images.length && !capabilities.vision(target.provider,target.model)){
    this.message(aiUi.text("Vælg en billedmodel til det vedhæftede screenshot."),true);return;
  }
  var messages=conversation.slice(-20).map(function(m){return {role:m.role,content:m.text.slice(0,9000)};});
  var expertRules=expert.buildExpertPrompt(last.text,($tw&&$tw.version)||"ukendt");
  messages.unshift({role:"system",content:aiUi.text("Du er HUWiki AI, en hjælpsom assistent til TiddlyWiki. Svar på brugerens sprog. Opfind ikke kilder. Du kan foreslå wikitext, tiddlere, filtre, tags og TiddlyWiki-arbejdsgange, men du kan ikke selv ændre wikien.")+"\n\n"+expert.formattingPrompt()+(expertRules?"\n\n"+expertRules:"")});
  var controller=(typeof AbortController!=="undefined")?new AbortController():null;
  var pixels=images.map(function(im){return im.width+"×"+im.height;}).join(", ");
  var job={started:Date.now(),controller:controller,cancelled:false,question:last.title,
    provider:target.provider,model:target.model,imageCount:images.length,imagePixels:pixels,
    imageKb:Math.round(images.reduce(function(n,im){return n+im.bytes;},0)/1024),
    imagePrepMs:images.reduce(function(n,im){return n+(im.prepMs||0);},0)};
  jobs[title]=job;this.scrollLatest=true;this.draw();
  this.request(messages,replyMode,function(err,response,serverTelemetry,replyImages){
    if(jobs[title]!==job||job.cancelled)return;
    delete jobs[title];
    if(err){failed[title]=aiUi.text("Kunne ikke hente svaret (efter ")+durationLabel(Date.now()-job.started)+"): "+err.message;}
    else if(!String(response||"").trim()&&!(replyImages&&replyImages.length)){failed[title]=aiUi.text("Modellen returnerede et tomt svar.");}
    else{
      var output=[];try{output=(replyImages||[]).map(imageReplies.validateImage);}catch(imageError){failed[title]=imageError.message;self.draw();return;}
      var telemetry=Object.assign({},serverTelemetry||{},{durationMs:Date.now()-job.started,
        remoteMs:Date.now()-job.started,imagePrepMs:job.imagePrepMs,provider:job.provider,model:job.model,outputImageCount:output.length});
      var replyTitle=chat.addMessage($tw.wiki,$tw.Tiddler,title,"assistant",response||(output.length?aiUi.text("Billedforslag – gem i AV for at beholde billedfilen."):""),new Date(),telemetry);
      if(output.length){self.outputImages=self.outputImages||Object.create(null);self.outputImages[replyTitle]=output;}delete failed[title];
    }
    if(self.selected===title){
      var currentStream=self.root&&self.root.querySelector(".huw-ai-chat-stream");
      self.scrollLatest=!currentStream||(currentStream.scrollHeight-currentStream.scrollTop-currentStream.clientHeight<100);
      self.draw();
    }
  },controller&&controller.signal,images,target,approval);
};
